+package main
+
+import (
+	"fmt"
+	"os"
+)
+
+// Simplified version of the BitSet structure and relevant functions
+type BitSet struct {
+	set    []uint64
+	length uint
+}
+
+const wordSize = 64
+const wordMask = wordSize - 1
+const log2WordSize = 6
+
+func wordsNeeded(i uint) int {
+	return int((i + wordMask) >> log2WordSize)
+}
+
+func (b *BitSet) extendSet(i uint) {
+	nsize := wordsNeeded(i + 1)
+	if b.set == nil {
+		b.set = make([]uint64, nsize)
+	} else if cap(b.set) >= nsize {
+		b.set = b.set[:nsize]
+	} else if len(b.set) < nsize {
+		newset := make([]uint64, nsize)
+		copy(newset, b.set)
+		b.set = newset
+	}
+	b.length = i + 1  // This is the problematic line
+}
+
+func (b *BitSet) Set(i uint) *BitSet {
+	if i >= b.length {
+		b.extendSet(i)
+	}
+	b.set[i>>log2WordSize] |= 1 << (i & wordMask)
+	return b
+}
+
+func (b *BitSet) Len() uint {
+	return b.length
+}
+
+func main() {
+	var b BitSet
+	
+	// Set a bit at index 100
+	b.Set(100)
+	fmt.Printf("After setting bit 100, length = %d\n", b.Len())
+	
+	// Set a bit at index 50
+	b.Set(50)
+	fmt.Printf("After setting bit 50, length = %d\n", b.Len())
+	
+	// The length should still be 101, not 51
+	if b.Len() != 101 {
+		fmt.Println("ERROR: Length tracking is incorrect!")
+		os.Exit(1)
+	} else {
+		fmt.Println("Length tracking is correct.")
+	}
+}

